actions.script:
const out = ec.service.sync().name('ironstone.ChatterServices.get#ChatterData').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else if (!out.visible) ec.web.sendJsonResponse({visible: false})
else ec.web.sendJsonResponse({visible: true, record: out.record, me: out.me, canMessage: out.canMessage, canSchedule: out.canSchedule,
    mayUpdate: out.mayUpdate, followerList: out.followerList, isFollowing: out.isFollowing, myKinds: out.myKinds,
    plannedActivities: out.plannedActivities, fileList: out.fileList, fileCount: out.fileCount, hasContent: out.hasContent,
    partyList: out.partyList, failedSources: out.failedSources})

const out = ec.service.sync().name('ironstone.RecordFilesServices.get#RecordFile').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', contentKey: contentKey || ''}).call()
if (!ec.message.hasError() && !out.contentLocation) ec.message.addError(ec.l10n.localize('This file has no content'))
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.contentLocation, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('ironstone.ChatterServices.get#Attachment').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', communicationEventContentId: communicationEventContentId || ''}).call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.contentLocation, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('ironstone.ChatterServices.cancel#Activity').parameters({recordEntityName: recordEntity, recordId: recordId,
    workEffortId: workEffortId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.ChatterServices.follow#Record').parameters({recordEntityName: recordEntity, recordId: recordId,
    kinds: kinds || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.ChatterServices.unfollow#Record').parameters({recordEntityName: recordEntity, recordId: recordId,
    userId: userId || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.ChatterServices.add#Followers').parameters({recordEntityName: recordEntity, recordId: recordId,
    userIds: userIds || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {addedUserIds: out.addedUserIds, messageInfos: [{type: 'success', message: out.message}]})
